/** The product details. */
export type Product = {
  /** The ID of the product. */
  id?: string;
  /** The product name. */
  name?: string;
  /** The product description. */
  description?: string;
  type?: "PHYSICAL" | "DIGITAL" | "SERVICE";
  category?: ProductCategory;
  /**
   * The image URL for the product.
   *
   * @format uri
   */
  image_url?: string;
  /**
   * The home page URL for the product.
   *
   * @format uri
   */
  home_url?: string;
  create_time?: DateTime;
  update_time?: DateTime;
  links?: LinkDescriptionList;
};

/** The details for a product in the collection response. */
export type ProductCollectionElement = {
  /** The ID of the product. */
  id?: string;
  /** The product name. */
  name?: string;
  /** The product description. */
  description?: string;
  create_time?: DateTime;
  links?: LinkDescriptionList;
};

/** An array of products. */
export type ProductCollectionElementList = ProductCollectionElement[];

/** The list of products, with details. */
export type ProductCollection = {
  products?: ProductCollectionElementList;
  /** The total number of items. */
  total_items?: number;
  /** The total number of pages. */
  total_pages?: number;
  links?: LinkDescriptionList;
};

/** The create product request details. */
export type ProductRequestPost = {
  /** The ID of the product. You can specify the SKU for the product. If you omit the ID, the system generates it. System-generated IDs have the `PROD-` prefix. */
  id?: string;
  /** The product name. */
  name: string;
  /** The product description. */
  description?: string;
  type: "PHYSICAL" | "DIGITAL" | "SERVICE";
  category?: ProductCategory;
  /**
   * The image URL for the product.
   *
   * @format uri
   */
  image_url?: string;
  /**
   * The home page URL for the product.
   *
   * @format uri
   */
  home_url?: string;
};

