export const ProductSchema: z.ZodType<Product> = z.object({
  id: z.string().min(6).max(50).optional(),
  name: z.string().min(1).max(127).optional(),
  description: z.string().min(1).max(256).optional(),
  type: z.enum(["PHYSICAL", "DIGITAL", "SERVICE"]).optional(),
  category: ProductCategorySchema.optional(),
  image_url: z.string().min(1).max(2000).optional(),
  home_url: z.string().min(1).max(2000).optional(),
  create_time: DateTimeSchema.optional(),
  update_time: DateTimeSchema.optional(),
  links: LinkDescriptionListSchema.optional(),
});

export const ProductCollectionElementSchema: z.ZodType<ProductCollectionElement> = z.object({
  id: z.string().min(6).max(50).optional(),
  name: z.string().min(1).max(127).optional(),
  description: z.string().min(1).max(256).optional(),
  create_time: DateTimeSchema.optional(),
  links: LinkDescriptionListSchema.optional(),
});

export const ProductCollectionElementListSchema: z.ZodType<ProductCollectionElementList> = z.array(
  ProductCollectionElementSchema,
).min(1).max(32767);

export const ProductCollectionSchema: z.ZodType<ProductCollection> = z.object({
  products: ProductCollectionElementListSchema.optional(),
  total_items: z.number().int().min(0).max(500000000).optional(),
  total_pages: z.number().int().min(0).max(100000000).optional(),
  links: LinkDescriptionListSchema.optional(),
});

export const ProductRequestPostSchema: z.ZodType<ProductRequestPost> = z.object({
  id: z.string().min(6).max(50).optional(),
  name: z.string().min(1).max(127),
  description: z.string().min(1).max(256).optional(),
  type: z.enum(["PHYSICAL", "DIGITAL", "SERVICE"]),
  category: ProductCategorySchema.optional(),
  image_url: z.string().min(1).max(2000).optional(),
  home_url: z.string().min(1).max(2000).optional(),
});

